class Solution {
public:
    int minRunesToAdd(int n, vector<int>& crystals, vector<int>& flowFrom, vector<int>& flowTo) {
        vector<vector<int>> g(n), rev(n);
        for (int i = 0; i < (int)flowFrom.size(); ++i) {
            g[flowFrom[i]].push_back(flowTo[i]);
            rev[flowTo[i]].push_back(flowFrom[i]);
        }
        vector<char> seen(n, false);
        vector<int> order;
        for (int s = 0; s < n; ++s) {
            if (seen[s]) continue;
            vector<pair<int, int>> st(1, {s, 0}); seen[s] = true;
            while (!st.empty()) {
                int u = st.back().first;
                int& idx = st.back().second;
                if (idx == (int)g[u].size()) { order.push_back(u); st.pop_back(); continue; }
                int v = g[u][idx++];
                if (!seen[v]) { seen[v] = true; st.push_back({v, 0}); }
            }
        }
        vector<int> comp(n, -1);
        int count = 0;
        for (int i = n - 1; i >= 0; --i) {
            int s = order[i];
            if (comp[s] != -1) continue;
            vector<int> st(1, s); comp[s] = count;
            while (!st.empty()) {
                int u = st.back(); st.pop_back();
                for (int v : rev[u]) if (comp[v] == -1) { comp[v] = count; st.push_back(v); }
            }
            ++count;
        }
        vector<int> indeg(count, 0);
        vector<char> sourceCrystal(count, false);
        for (int x : crystals) sourceCrystal[comp[x]] = true;
        for (int i = 0; i < (int)flowFrom.size(); ++i)
            if (comp[flowFrom[i]] != comp[flowTo[i]]) ++indeg[comp[flowTo[i]]];
        int ans = 0;
        for (int i = 0; i < count; ++i)
            if (indeg[i] == 0 && !sourceCrystal[i]) ++ans;
        return ans;
    }
};
